sku_code = #{skuCode}, spec_json = #{specJson}, price = #{price}, cost = #{cost}, stock = #{stock}, threshold = #{threshold}, status = #{status}, update_time = NOW()
WHERE id = #{id} AND company_id = #{companyId}

UPDATE opc_erp_product_sku
SET stock = #{stock},
    version = version + 1,
    update_time = NOW()
WHERE id = #{id}
  AND company_id = #{companyId}
  AND version = #{version}

